+import { LINEAR_UNITS, TEMPERATURE_UNITS, type Kind } from "./units.ts";
+
+type TemperatureUnit = (typeof TEMPERATURE_UNITS)[number];
+
+const ABSOLUTE_ZERO: Record<TemperatureUnit, number> = {
+  C: -273.15,
+  F: -459.67,
+  K: 0,
+};
+
+function isTemperature(unit: string): unit is TemperatureUnit {
+  return (TEMPERATURE_UNITS as readonly string[]).includes(unit);
+}
+
+function kindOf(unit: string): Kind | "temperature" | undefined {
+  if (isTemperature(unit)) return "temperature";
+  if (Object.hasOwn(LINEAR_UNITS, unit)) return LINEAR_UNITS[unit].kind;
+  return undefined;
+}
+
+function toCelsius(value: number, unit: TemperatureUnit): number {
+  switch (unit) {
+    case "C":
+      return value;
+    case "F":
+      return ((value - 32) * 5) / 9;
+    case "K":
+      return value - 273.15;
+  }
+}
+
+function fromCelsius(celsius: number, unit: TemperatureUnit): number {
+  switch (unit) {
+    case "C":
+      return celsius;
+    case "F":
+      return (celsius * 9) / 5 + 32;
+    case "K":
+      return celsius + 273.15;
+  }
+}
